update_rule.pseudocode:
for each Household H:
  hh_rate = mean(wearing_mask for members of H)
  for each member p in H:
    pressure[p] = household_norm_weight * H.norm_strength * (hh_rate - 0.5)

for each Person p:
  neighbor_rate = mean(wearing_mask of p.network_neighbors)
  influence[p] = base_influence_strength * p.social_influence_susceptibility * (neighbor_rate - 0.5)

compliance_obs = []
for each visit (person p -> location L):
  if policy_state == 'mandate' and L.type != 'household':
    required = True
    enforcement = clamp(Normal(enforcement_level_default, enforcement_location_sd), 0, 1)
    pressure = policy_effect_strength * p.trust_in_authority * enforcement
    if random() < ticket_probability and not p.wearing_mask:
      apply penalty cost = fine_amount (adds to perceived cost)
    if access_blocking and not p.wearing_mask and random() < enforcement:
      mark p as denied; reduce contacts for p at L
    record compliance_obs.append(p.wearing_mask)
  else:
    pressure = 0
  location_policy_pressure[p] += pressure
emit observable.compliance = mean(compliance_obs) if any else previous

for each Person p:
  determine schedule: household + work/school/public based on mobility_rate
  for each scheduled location type:
    sample number_of_contacts from Poisson(daily_contacts_by_type)
    for each contact:
      sample counterpart mask status from distribution at location (previous day or running estimate)
      record unprotected_contact = (not p.wearing_mask) or (counterpart not wearing) with efficacy weighting later
  compute observed norms per location type as fraction masked among present
aggregate observable.contacts_unprotected_daily as total unprotected contacts

for each Person p:
  policy_signal = policy_effect_strength * policy_enforcement_level * p.trust_in_authority + policy.signage_effect
  utility_masked = baseline_adoption_bias + risk_perception_weight * p.risk_perception + signal.peer_influence[p] + signal.household_norm_pressure[p] + policy_signal + signal.location_policy_pressure[p] - fatigue_effect_strength * p.fatigue_level + Normal(0, compliance_noise)
  utility_unmasked = 0
  choose_type_utility[type] = type_preference_weight * mask_efficacy[type] - p.cost_sensitivity * (prices.current[type]/mask_lifespan_days[type])
  selected_type = argmax_type choose_type_utility
  if not p.wearing_mask:
    p_adopt = sigmoid(utility_masked - utility_unmasked)
    if random() < p_adopt:
      issue purchase_request(p, selected_type)
  else:
    # retention decision
    p_keep = sigmoid(utility_masked - utility_unmasked)
    if random() >= p_keep:
      p.wearing_mask = False; p.mask_type = None
  process purchase_outcomes after market module:
    if fulfilled:
      p.wearing_mask = True; p.mask_type = selected_type; update internal mask_tenure[p]
      record mask_type_distribution
  update fatigue: p.fatigue_level = clamp(p.fatigue_level + fatigue_rate*(1 if p.wearing_mask else -1), 0, 1)

adoption_rate = mean(p.wearing_mask)
adoption_rate_by_income = {group: mean(p.wearing_mask for p in group)}
mask_type_share = {type: count(p.mask_type==type)/max(1, count(p.wearing_mask))}
policy_state_daily = current policy state
exposure_reduction = contacts_unprotected_daily_weighted = total_contacts * (1 - (adoption_rate * mean_efficacy))
emit observables
